<script>
import api from '../api.js';
import uiState from '../uiState.js';
export default {
 name:'SearchTypes',props:['project','target','screen','user','allowWrites'],emits:['open','changed','dirty'],
 data(){return {types:[],selected:'',detail:null,tab:'columns',adding:false,name:'',title:'',description:'',columns:[],pipeline:false,preview:false,busy:false,error:'',message:'',filter:'',metadata:{},newColumns:[],designer:null,designerField:null,seq:0,dependencies:null,dependencyField:'',stateReady:false,importDirty:false}},
 computed:{canCreate(){return this.allowWrites&&!['admin','sthpw','default'].includes(this.project)},visibleTypes(){const q=this.filter.toLowerCase();return this.types.filter(t=>(t.code+' '+t.name).toLowerCase().includes(q))},dirty(){return this.importDirty||this.adding||this.newColumns.length>0||!!this.detail&&JSON.stringify(this.metadata)!==JSON.stringify(this.detail.metadata)}},
 watch:{dirty(v){this.$emit('dirty',v)},selected(){this.storeState()},tab(){this.storeState()}},async mounted(){await this.load();try{const s=await uiState.load({...this.args(),scope:'stype-editor'});const code=this.screen?.search_type||s.value?.selected;if(code&&this.types.some(t=>t.code===code))await this.choose(code);if(s.value?.tab)this.tab=s.value.tab}catch(e){this.error=e.message}this.stateReady=true},beforeUnmount(){this.seq++},
 methods:{
 storeState(){if(this.stateReady)uiState.schedule({...this.args(),scope:'stype-editor'},{selected:this.selected,tab:this.tab})},
 args(){return {project:this.project,target:this.target}},
 async load(){this.error='';try{this.types=(await api.request('/stype-editor',this.args())).types||[]}catch(e){this.error=e.message}},
 async choose(code){if(this.dirty&&!confirm('Отменить несохранённые изменения SearchType?'))return;this.adding=false;this.importDirty=false;this.dependencies=null;this.newColumns=[];const seq=++this.seq;this.busy=true;this.error='';try{const d=await api.request('/stype-editor',{...this.args(),search_type:code});if(seq!==this.seq)return;this.selected=code;this.detail=d;this.metadata={...d.metadata}}catch(e){if(seq===this.seq)this.error=e.message}finally{if(seq===this.seq)this.busy=false}},
 async create(){if(this.busy)return;this.busy=true;this.error='';this.message='';try{const r=await api.request('/search-types',{...this.args(),name:this.name,title:this.title,description:this.description,columns:this.columns,pipeline:this.pipeline,preview:this.preview},'POST');this.adding=false;this.name='';this.title='';this.description='';this.columns=[];await this.load();this.detail=null;await this.choose(r.search_type);this.message='Создан '+r.search_type+' исходной SearchTypeCreatorCmd';this.$emit('changed')}catch(e){this.error=e.message}finally{this.busy=false}},
 async saveMetadata(){if(this.busy)return;this.busy=true;this.error='';try{await api.request('/stype-editor',{...this.args(),search_type:this.selected,revision:this.detail.revision,values:this.metadata},'PATCH');this.detail.metadata={...this.metadata};const code=this.selected;await this.load();await this.choose(code);this.message='Метаданные исходного SearchType сохранены';this.$emit('changed')}catch(e){this.error=e.message}finally{this.busy=false}},
 async addColumns(){if(this.busy||!this.newColumns.length)return;if(!confirm('Добавить физические колонки в базу проекта? Убедитесь, что есть резервная копия. Удаление/откат здесь не выполняется.'))return;this.busy=true;this.error='';try{const r=await api.request('/stype-editor',{...this.args(),search_type:this.selected,revision:this.detail.revision,columns:this.newColumns,confirm:'ADD_COLUMNS'},'POST');this.newColumns=[];await this.choose(this.selected);this.message=r.notice;this.$emit('changed')}catch(e){this.error=e.message}finally{this.busy=false}},
 openDesigner(view,field=null){this.designerField=field;if(this.dirty||this.busy){this.error='Сначала сохраните или отмените метаданные и новые колонки';return}this.designer=view},
 async inspectDependencies(field=''){if(this.busy)return;this.busy=true;this.error='';try{this.dependencies=await api.request('/stype-dependencies',{...this.args(),search_type:this.selected,field});this.dependencyField=field;this.tab='references'}catch(e){this.error=e.message}finally{this.busy=false}},
 openTool(tool){if(this.dirty){this.error='Сначала сохраните или отмените черновик';return}this.$emit('open',{id:this.target+'/~admin/stype-tool:'+tool+':'+encodeURIComponent(this.selected)})},
 selectTab(tab){if(this.importDirty&&this.tab==='import'&&tab!=='import'&&!confirm('Отменить CSV-черновик?'))return;this.importDirty=false;this.tab=tab},
 openTable(){this.$emit('open',{id:this.target+'/~admin/stype-table:'+encodeURIComponent(this.selected)})},
 startCreate(){if(this.dirty&&!confirm('Отменить текущие правки?'))return;this.adding=true;this.detail=null;this.newColumns=[]},
 async definitionSaved(){this.designer=null;this.newColumns=[];this.detail=null;await this.choose(this.selected);this.$emit('changed')}
 }
};
</script>
<template>
<section class="stype-workbench" aria-label="Manage SearchTypes"><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p>
<div class="admin-two-pane"><aside class="admin-catalog"><div class="catalog-actions"><button :disabled="!canCreate||busy" class="primary" @click="startCreate">Новый SearchType</button></div><input v-model="filter" type="search" placeholder="Найти SearchType…"><button v-for="t in visibleTypes" :key="t.code" class="admin-catalog-item" :aria-selected="selected===t.code&&!adding" @click="choose(t.code)"><b>{{t.name}}</b><code>{{t.code}}</code><small v-if="!t.can_write">Общий / только чтение</small></button><p v-if="!types.length" class="muted">Нет проектных типов. Выберите рабочий проект.</p></aside><main class="admin-editor-pane">
<form v-if="adding" class="type-create" @submit.prevent="create"><h3>Новый SearchType / {{project}}</h3><div class="field-grid"><label>Системное имя<input v-model="name" pattern="[a-z][a-z0-9_]{0,49}" required></label><label>Название<input v-model="title" maxlength="200" required></label></div><label>Описание<textarea v-model="description" rows="2"></textarea></label><h4>Дополнительные поля</h4><p class="muted">Стандартные id, code, name, description и служебные поля создаются TACTIC.</p><div v-for="(c,i) in columns" :key="i" class="column-row"><input v-model="c.name" pattern="[a-z][a-z0-9_]{0,49}" placeholder="Имя поля" required><select v-model="c.type"><option v-for="t in ['varchar','text','integer','float','boolean','timestamp','date','json']" :key="t" :value="t">{{t}}</option></select><button type="button" @click="columns.splice(i,1)">×</button></div><button type="button" :disabled="columns.length>=50" @click="columns.push({name:'',type:'varchar'})">Добавить поле</button><div class="toolbar"><label><input type="checkbox" v-model="pipeline"> Пайплайн</label><label><input type="checkbox" v-model="preview"> Превью</label></div><p class="notice">Изменяет схему базы. Существующие таблицы не переиспользуются. При обрыве проверьте результат перед повтором.</p><div class="toolbar"><button class="primary" :disabled="busy">Создать через TACTIC</button><button type="button" @click="adding=false">Отменить</button></div></form>
<template v-else-if="detail"><header class="toolbar"><code>{{selected}}</code><span class="spacer"></span><button @click="openTable" aria-label="Открыть таблицу">Таблица</button><button @click="openTool('insert')">Новая запись</button><button @click="openTool('workflow')">Workflow</button><button @click="openTool('schema')">Schema</button><button :disabled="dirty||busy" @click="choose(selected)">Обновить</button></header><nav class="admin-section-tabs"><button :aria-selected="tab==='columns'" @click="selectTab('columns')">Колонки</button><button :aria-selected="tab==='metadata'" @click="selectTab('metadata')">SearchType</button><button :aria-selected="tab==='views'" @click="selectTab('views')">Представления</button><button :aria-selected="tab==='references'" @click="selectTab('references');inspectDependencies()">Ссылки</button><button :disabled="!detail.can_write" :aria-selected="tab==='import'" @click="selectTab('import')">CSV-импорт</button></nav><p v-if="!detail.can_write" class="notice">Системный или общий тип: изменение его физической схемы и регистрации здесь запрещено. Конфигурации текущего проекта доступны отдельно.</p>
<section v-if="tab==='columns'"><p class="muted">{{detail.notice}}</p><div class="table-scroll"><table class="schema-editor-table"><thead><tr><th>Колонка</th><th>Тип БД</th><th>Display / edit definition</th></tr></thead><tbody><tr v-for="c in detail.columns" :key="c.name"><td><b>{{c.name}}</b></td><td><code>{{c.schema?.data_type||c.schema?.type||JSON.stringify(c.schema)}}</code></td><td><small>{{c.definition.handler||'По умолчанию'}}</small><small>{{c.edit_definition.edit_handler||c.edit_definition.handler||'По умолчанию'}}</small><button @click="openDesigner('definition',c.name)">Определение</button><button @click="inspectDependencies(c.name)">Ссылки</button></td></tr></tbody></table></div><div class="toolbar"><button @click="openDesigner('definition')">Определения display…</button><button @click="openDesigner('edit_definition')">Определения edit…</button><span class="spacer"></span><button :disabled="!detail.can_write||newColumns.length>=30" @click="newColumns.push({name:'',data_type:'varchar',format:''})">Добавить физическую колонку</button></div><form v-if="newColumns.length" class="new-columns-form" @submit.prevent="addColumns"><div v-for="(c,i) in newColumns" :key="i" class="column-row"><input v-model="c.name" pattern="[a-z][a-z0-9_]{0,49}" required placeholder="Имя колонки"><select v-model="c.data_type"><option v-for="t in detail.column_types" :key="t">{{t}}</option></select><select v-model="c.format"><option value="">Без форматирования</option><option v-for="f in detail.formats.filter(Boolean)" :key="f">{{f}}</option></select><button type="button" @click="newColumns.splice(i,1)">×</button></div><p class="notice">Выполнится ColumnEditCbk → ColumnAddCmd с записью definition/edit_definition. Состав таблицы задаётся отдельно её view.</p><button class="primary" :disabled="busy">Создать {{newColumns.length}} колонок</button></form></section>
<form v-else-if="tab==='metadata'" @submit.prevent="saveMetadata"><div class="field-grid"><label>Название<input v-model="metadata.title" :readonly="!detail.can_write" required></label><label>Цвет<input v-model="metadata.color" :readonly="!detail.can_write" placeholder="#RRGGBB"></label></div><label>Описание<textarea v-model="metadata.description" :readonly="!detail.can_write" rows="4"></textarea></label><dl class="system-summary"><div v-for="(v,k) in detail.registry" :key="k" class="system-fact"><dt>{{k}}</dt><dd><code>{{v}}</code></dd></div></dl><button class="primary" :disabled="busy||!detail.can_write||!dirty">Сохранить метаданные</button></form>
<div v-else-if="tab==='views'"><button @click="openTool('views')">Открыть Manage Views</button><div class="admin-view-row" v-for="v in detail.views" :key="v.name"><b>{{v.name}}</b><span>{{v.elements.join(', ')||'Пустое представление'}}</span><button @click="openDesigner(v.name)">Редактировать widget_config</button></div><p class="muted">Порядок полей, display/edit/action и параметры остаются в исходных XML-конфигурациях.</p></div>
<section v-else-if="tab==='references'"><p class="notice">Статические кандидаты текущего проекта, не доказательство отсутствия динамических зависимостей. Удаление и изменение типа колонок этим экраном не выполняются.</p><button :disabled="busy" @click="inspectDependencies(dependencyField)">Обновить ссылки {{dependencyField}}</button><template v-if="dependencies"><p>Связи Schema: {{dependencies.related_types.join(', ')||'нет'}}</p><div class="admin-view-row" v-for="r in dependencies.references" :key="r.key"><code>{{r.kind}}</code><span>{{r.name}}</span><small>{{r.views.join(', ')}}</small></div><p v-if="!dependencies.references.length">В проверенных записях совпадений нет.</p><p v-for="e in dependencies.errors" :key="e.key" class="notice">{{e.key}}: {{e.reason}}</p></template></section>
<CsvImportPanel v-else-if="tab==='import'" :key="selected" :project="project" :target="target" :search-type="selected" @dirty="importDirty=$event" @saved="$emit('changed')"/>
</template><p v-else class="muted">Выберите SearchType слева или создайте новый.</p>
</main></div><ViewDesigner v-if="designer" :project="project" :search-type="selected" :initial-view="designer" :initial-element="designerField" :login="user?.login" @close="designer=null" @saved="definitionSaved"/></section>
</template>
